-- ============================================
-- LUMA — Thème 6 : LONG 1/3 x4 — Une tension qui dégénère et se résout
-- ============================================


update scenarios set content = '{"characters": {"roommate": "ton/ta coloc"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate", "text": "(Sighs loudly while cleaning up dishes in the sink.) Again? Seriously?", "text_fr": "(Soupire fort en nettoyant la vaisselle dans l''évier.) Encore ? Sérieusement ?", "choices": [{"text": "Sorry, I was going to do them tonight, I just got busy.", "text_fr": "Désolé, j''allais les faire ce soir, j''étais juste occupé.", "next": "n2"}, {"text": "(Feel a bit defensive) It''s not a huge deal, I would''ve handled it.", "text_fr": "(Te sens un peu sur la défensive) C''est pas un gros problème, je m''en serais occupé.", "next": "n2b"}]}, "n2": {"speaker": "roommate", "text": "This happens like every week now. I feel like I''m always the one cleaning up.", "text_fr": "Ça arrive genre chaque semaine maintenant. J''ai l''impression d''être toujours celui/celle qui nettoie.", "choices": [{"text": "You''re right, I haven''t been pulling my weight lately.", "text_fr": "T''as raison, j''ai pas fait ma part dernièrement.", "next": "n3"}, {"text": "I don''t think that''s totally fair, I do plenty around here too.", "text_fr": "Je pense pas que ce soit totalement juste, je fais aussi beaucoup ici.", "next": "n3b"}]}, "n2b": {"speaker": "roommate", "text": "(Getting more frustrated) It kind of is a big deal when it happens constantly!", "text_fr": "(De plus en plus frustré) C''est un peu un gros problème quand ça arrive constamment !", "choices": [{"text": "Okay, I hear you, let''s talk about this properly.", "text_fr": "OK, je t''entends, parlons de ça correctement.", "next": "n3"}, {"text": "(Feel the tension rising) Fine, I''ll do them right now then.", "text_fr": "(Sens la tension monter) OK, je les fais tout de suite alors.", "next": "n3c"}]}, "n3": {"speaker": "roommate", "text": "I appreciate you saying that. It''s just been building up for a while.", "text_fr": "J''apprécie que tu dises ça. Ça s''accumule depuis un moment.", "choices": [{"text": "I didn''t realize it had gotten to this point, I''m sorry.", "text_fr": "Je réalisais pas que c''était arrivé à ce point, désolé.", "next": "n4"}]}, "n3b": {"speaker": "roommate", "text": "(Voice raising slightly) I feel like you always say that, but nothing changes!", "text_fr": "(Voix qui monte légèrement) J''ai l''impression que tu dis toujours ça, mais rien ne change !", "choices": [{"text": "(Take a breath) You''re right to be frustrated. Let''s actually talk this through.", "text_fr": "(Prends une respiration) T''as raison d''être frustré. Parlons-en vraiment.", "next": "n4"}, {"text": "That''s not fair, I do plenty of other things around here!", "text_fr": "C''est pas juste, je fais plein d''autres choses ici !", "next": "n4b"}]}, "n3c": {"speaker": "roommate", "text": "That''s not really the point — I need to know I can count on you consistently.", "text_fr": "C''est pas vraiment le sujet — j''ai besoin de savoir que je peux compter sur toi de façon régulière.", "choices": [{"text": "You''re right, doing them now doesn''t fix the pattern. Let''s actually talk.", "text_fr": "T''as raison, les faire maintenant règle pas le schéma. Parlons-en vraiment.", "next": "n4"}]}, "n4": {"speaker": "roommate", "text": "I just want this to feel fair for both of us, you know?", "text_fr": "Je veux juste que ça semble juste pour nous deux, tu comprends ?", "choices": [{"text": "Me too. Let''s figure out a system that actually works this time.", "text_fr": "Moi aussi. Trouvons un système qui fonctionne vraiment cette fois.", "next": "n5"}]}, "n4b": {"speaker": "roommate", "text": "(The tension peaks) This isn''t just about dishes, it''s about feeling respected here!", "text_fr": "(La tension atteint son pic) C''est pas juste une question de vaisselle, c''est une question de se sentir respecté ici !", "choices": [{"text": "(Pause, realizing this matters more than it seemed) You''re right. I''m sorry, let''s really talk.", "text_fr": "(Fait une pause, réalisant que c''est plus important qu''il n''y paraissait) T''as raison. Désolé, parlons-en vraiment.", "next": "n5"}]}, "n5": {"speaker": "roommate", "text": "Thank you for hearing me out. What if we made a simple rotating schedule?", "text_fr": "Merci de m''avoir écouté. Et si on faisait un simple planning rotatif ?", "choices": [{"text": "That sounds good — should we write it down somewhere visible?", "text_fr": "Ça a l''air bien — on devrait l''écrire quelque part visible ?", "next": "n6"}, {"text": "I like that, maybe with reminders on our phones too?", "text_fr": "J''aime bien, peut-être avec des rappels sur nos téléphones aussi ?", "next": "n6"}]}, "n6": {"speaker": "roommate", "text": "Yeah, let''s put it on the fridge, so we both see it daily.", "text_fr": "Ouais, mettons-le sur le frigo, comme ça on le voit tous les deux tous les jours.", "choices": [{"text": "Perfect, and let''s check in weekly to see how it''s going.", "text_fr": "Parfait, et faisons le point chaque semaine pour voir comment ça se passe.", "next": "n7"}]}, "n7": {"speaker": "roommate", "text": "I really appreciate you being open to this conversation, even though it was tense.", "text_fr": "J''apprécie vraiment que tu sois ouvert à cette conversation, même si c''était tendu.", "choices": [{"text": "Me too, honestly. I''d rather we talk it out than let it build up again.", "text_fr": "Moi aussi, honnêtement. Je préfère qu''on en parle plutôt que ça s''accumule encore.", "next": "n8"}]}, "n8": {"speaker": "roommate", "text": "Agreed. I think we''re actually going to be fine living together.", "text_fr": "D''accord. Je pense qu''on va vraiment bien s''en sortir en vivant ensemble.", "choices": [{"text": "Same here. Thanks for caring enough to bring it up.", "text_fr": "Pareil pour moi. Merci de te soucier assez pour en parler.", "next": "end_resolved"}]}, "end_resolved": {"speaker": "roommate", "text": "Of course. This is what makes a house actually feel like a home.", "text_fr": "Bien sûr. C''est ce qui fait qu''une maison ressemble vraiment à un foyer.", "end": true, "ending_label": "Conflit résolu, relation renforcée 🏠💪"}}}'::jsonb, is_playable = true
where title = 'Une tension qui dégénère et se résout'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
